"use client";

import "./toast.css";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { cx } from "./cx";

export type ToastTone = "default" | "success" | "warning" | "danger" | "info";

type ToastItem = {
  id: string;
  message: ReactNode;
  tone: ToastTone;
  timeout: number;
  className?: string | undefined;
};

type Timer = {
  handle: number;
  remaining: number;
  started: number;
};

export type ToastOptions = {
  tone?: ToastTone | undefined;
  timeout?: number | undefined;
  className?: string | undefined;
};

type ToastContextValue = {
  toast: (message: ReactNode, options?: ToastOptions | undefined) => string;
  dismiss: (id: string) => void;
};

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast() {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error("useToast must be used inside ToastProvider.");
  return ctx;
}

export type ToastProviderProps = {
  children: ReactNode;
};

export function ToastProvider({ children }: ToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);
  const timers = useRef(new Map<string, Timer>());

  const dismiss = useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (timer) window.clearTimeout(timer.handle);
    timers.current.delete(id);
    setItems((current) => current.filter((item) => item.id !== id));
  }, []);

  const arm = useCallback(
    (id: string, remaining: number) => {
      if (remaining <= 0) return;
      timers.current.set(id, {
        handle: window.setTimeout(() => dismiss(id), remaining),
        remaining,
        started: Date.now(),
      });
    },
    [dismiss],
  );

  const pause = useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (!timer) return;
    window.clearTimeout(timer.handle);
    timer.remaining = Math.max(0, timer.remaining - (Date.now() - timer.started));
    timer.handle = 0;
  }, []);

  const resume = useCallback(
    (id: string) => {
      const timer = timers.current.get(id);
      if (!timer || timer.handle) return;
      arm(id, timer.remaining);
    },
    [arm],
  );

  const toast = useCallback(
    (message: ReactNode, options?: ToastOptions | undefined) => {
      const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const tone = options?.tone ?? "default";
      const timeout = options?.timeout ?? 4000;
      const className = options?.className;
      setItems((current) => [
        ...current,
        { id, message, tone, timeout, className },
      ]);
      if (timeout > 0) arm(id, timeout);
      return id;
    },
    [arm],
  );

  useEffect(() => {
    const active = timers.current;
    return () => {
      for (const timer of active.values()) window.clearTimeout(timer.handle);
    };
  }, []);

  return (
    <ToastContext.Provider value={{ toast, dismiss }}>
      {children}
      <div
        className="ns-toast-region"
        role="region"
        aria-label="Notifications"
      >
        {items.map((item) => (
          <div
            key={item.id}
            className={cx("ns-toast", item.className)}
            data-tone={item.tone}
            role={item.tone === "danger" ? "alert" : "status"}
            aria-atomic="true"
            onMouseEnter={() => pause(item.id)}
            onMouseLeave={() => resume(item.id)}
            onFocus={() => pause(item.id)}
            onBlur={() => resume(item.id)}
          >
            <div className="ns-toast__message">{item.message}</div>
            <button
              type="button"
              className="ns-toast__dismiss"
              aria-label="Dismiss"
              onClick={() => dismiss(item.id)}
            >
              ×
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

@layer components {
  .ns-toast-region {
    position: fixed;
    inset-block-end: var(--space-8, 1.19rem);
    inset-inline-end: var(--space-8, 1.19rem);
    z-index: var(--z-toast, 30);
    display: flex;
    flex-direction: column;
    gap: var(--space-4, 0.49rem);
    width: min(22rem, calc(100% - var(--space-10, 1.86rem)));
    pointer-events: none;
  }

  .ns-toast {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-4, 0.49rem);
    padding: var(--space-8, 1.19rem);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    background: var(--face);
    background-clip: padding-box;
    color: var(--text-heading, #111);
    font-weight: var(--weight-medium, 500);
    line-height: var(--leading-tight, 1.25);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    pointer-events: auto;
  }

  .ns-toast__message {
    min-width: 0;
  }

  .ns-toast__dismiss {
    appearance: none;
    flex-shrink: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: inherit;
    cursor: pointer;
    font: inherit;
    line-height: 1;
    opacity: 0.7;
  }

  .ns-toast__dismiss:hover,
  .ns-toast__dismiss:focus-visible {
    opacity: 1;
  }

  /* Tone is the message ink, on the same silver chrome as every other tone. */
  .ns-toast[data-tone="success"] {
    color: var(--success, #2f6b3a);
  }

  .ns-toast[data-tone="warning"] {
    color: var(--warning, #8a5a12);
  }

  .ns-toast[data-tone="danger"] {
    color: var(--error, #8f3232);
  }

  .ns-toast[data-tone="info"] {
    color: var(--info, #2c4a6e);
  }
}
